/* Loại bỏ mục trùng lặp và ký tự không phải kanji, chỉ giữ lần xuất hiện đầu tiên.
   `exclude` để bảng N4 không lặp lại những chữ đã có trong bảng N5. */
function dedupeKanji(list, exclude) {
  const seen = new Set(exclude || []);
  return list.filter(k => {
    const ok = /^[一-鿿]$/.test(k.c) && !seen.has(k.c);
    if (ok) seen.add(k.c);
    return ok;
  });
}

const KANJI = {};
KANJI.N5 = dedupeKanji(KANJI_N5);
KANJI.N4 = dedupeKanji(KANJI_N4, KANJI.N5.map(k => k.c));

// Gắn nhãn trình độ vào từng chữ để phần ôn tập biết chữ đó thuộc cấp nào
KANJI.N5.forEach(k => { k.lv = 'N5'; });
KANJI.N4.forEach(k => { k.lv = 'N4'; });
KANJI.ALL = KANJI.N5.concat(KANJI.N4);
